import{_ as t,o as e,c as o,y as s}from"./chunks/framework.CNTkXYA8.js";const m=JSON.parse('{"title":"初中总结＆高中规划","description":"","frontmatter":{"title":"初中总结＆高中规划","date":"2020-08-24T21:57:00.000Z"},"headers":[],"relativePath":"blog/post-13556621.md","filePath":"source/old_posts/post-13556621.md"}'),a={name:"blog/post-13556621.md"};function _(r,p,n,c,d,l){return e(),o("div",null,[...p[0]||(p[0]=[s("<p>一、初中总结</p><p>在初中生活中，我收获良多。</p><p>在学习上，我努力学习各门功课，合理安排时间，劳逸结合，上课认真听讲，回家及时巩固复习，掌握科学的学习方法，利用各种资源拓宽我的知识面。</p><p>在体育方面，我经常锻炼，跑步在班级里是前几名。在学习之余我还会打篮球，培养自己的坚强意志和坚韧品格，努力做到身体健康。身体是革命的本钱，我深深地明白这一点。</p><p>在品德方面，我遵守学校纪律，尊敬老师，热爱集体，不做有损集体荣誉的事。我严格要求自己，尽量不让自己出现品德上的瑕疵。</p><p>在审美方面，我喜欢阅读各类文学作品。我喜欢阅读契科夫的作品，也喜欢看一些社会学方面的书籍，让我对宏观的现象有了分析的能力，让我积累了人生的经验。</p><p>在日常生活中，我尊敬长辈，在课余常做家务，深刻地理解劳动之可贵。我在初中四年也担任了班班通管理员和信息课代表，为同学们服务，这让我感到为集体的付出是无比令人愉悦的。</p><p>对于初中四年，我感悟到学习的成绩不是人生的第一要义，在努力学习时，时时刻刻记住要先学会思考，学会做人，要有理想、有抱负，才能成为一个对社会有用的人才；时光很短暂，初中四年弹指一挥间，这让我懂得了时间的可贵，一旦失去青春就再也无法挽回。在初中三年，我的学习方面有一些不足，没有全力以赴地执行所有的学习任务，在高中的三年，我将会努力学习，奋发拼搏，努力向上，成为有能力，好钻研，肯拼搏的青少年。</p><p>高一六班　zzy</p><p>二、高中生涯规划</p><p>在高一的时候我将会努力学习，争取拿到班级前十的名次；同时也会学习信息竞赛，在时间比较充裕的高一努力学习。</p><p>１.认真投入到繁忙的学习中，把学习作为日常生活的一部分，用良好的态度面对学习。挑战自己，相信自己，要用有限的时间投入到无限的学习中去。</p><p>２.以课本为主，上课学会科学地记笔记，以课外资料为辅，层层递进提高。我还要建立一本错题本，记录错题，解决巩固。</p><p>３.实事求是，不懂的问题就是不懂，不会的题目要自己弄懂，如果还是不会则要求助于同学、老师。</p><p>４.不偏科，不因为之后的选科而只学几门课程，重视所有的科目，查漏补缺，形成严谨的态度。</p><p>５.做好时间管理，每天不熬夜，晚上有条不紊地复习各科，早上起来去学校要早，中午休息时即使不困也要闭眼。</p><p>６.积极参加集体活动，例如课外活动等，认真准备，积极参与，学习生活中的经验。</p><p>７.尊重老师，尊重同学，遵守校规校纪，学习法律观念，学好政治课，在思想上对自己严格把控。</p><p>高二时间开始紧张，要专注于学习和锻炼，参加最后一次竞赛，其它的事情能免则免。</p><p>高三冲刺高考，全力以赴。</p><p>高一六班　zzy</p>",21)])])}const f=t(a,[["render",_]]);export{m as __pageData,f as default};
